const p = $('Fälligen Post holen').first().json;
// Kanal (Stefan 17.10.2026): linkedin_profil (persönliches Profil) oder linkedin_seite (Unternehmensseite)
const seite = p.kanal === 'linkedin_seite';
const textDatei = seite ? 'LinkedIn/linkedin-seite.txt' : 'LinkedIn/linkedin-profil.txt';
const prof = $('Profil (LinkedIn)').first().json || {};
// Dateien im Themenordner (SPEICHER 1): Text wurde geholt, die übrigen Dateien nur geprüft
const vor = $('Dateien vorbereiten').all().map(i => i.json);
const erg = $input.all().map(i => i.json);
const ort = (erg[0] && erg[0].ort) || 'Speicherort';
const da = rel => { const e = erg[vor.findIndex(v => v.rel === rel)] || {}; return e.ok === true && e.vorhanden === true && e.ordner !== true; };
const speicherFehler = (erg.find(e => e.ok !== true) || {}).fehler || '';
const geholt = $('Text holen (SPEICHER 1)').first().json || {};
let text = String((vor[0] || {}).lesetext || '').trim();
const quelle = text ? ort + ' (' + textDatei + ')' : 'Datenbank';
const textNichtLesbar = !text && da(textDatei) && geholt.ok !== true;
if (!text) text = String(p.text_db || '').trim();
const erste = liste => liste.find(da) || '';
const datei = p.format === 'pdf' ? erste(['LinkedIn/karussell-linkedin.pdf', 'karussell-linkedin.pdf']) : (p.format === 'bild' ? erste(['Instagram-Post/karussell-01.jpg', 'Instagram-Post/karussell-01.png', 'karussell-01.png']) : '');

let fehler = '';
// LinkedIn je Person (Stefan 17.10.2026): jede Person verbindet ihr eigenes LinkedIn in der Oberfläche (ALLY 12)
if (!p.linkedin_token) fehler = seite ? 'Die Unternehmensseite ist nicht verbunden. Ein Admin verbindet sie unter Einstellungen › Marketing › Veröffentlichen › LinkedIn. Danach den Beitrag erneut freigeben.'
  : 'Dein persönliches LinkedIn-Profil ist nicht verbunden. Bitte unter Einstellungen › Marketing › Veröffentlichen › LinkedIn verbinden und den Beitrag dann erneut freigeben.';
else if (seite ? !(prof.id || prof.localizedName) : !prof.sub) fehler = seite ? 'Die Verbindung zur Unternehmensseite ist abgelaufen oder ungültig. Ein Admin verbindet sie unter Einstellungen › Marketing › Veröffentlichen › LinkedIn neu.'
  : 'Deine LinkedIn-Verbindung ist abgelaufen oder ungültig. Bitte unter Einstellungen › Marketing › Veröffentlichen › LinkedIn neu verbinden und den Beitrag dann erneut freigeben.';
else if (speicherFehler) fehler = 'Der Themenordner im Speicherort (' + ort + ') konnte nicht gelesen werden: ' + speicherFehler;
else if (textNichtLesbar) fehler = 'Die Datei ' + textDatei + ' konnte nicht gelesen werden: ' + (geholt.fehler || 'unbekannter Fehler');
else if (!text) fehler = 'Kein LinkedIn-Text gefunden.';
else if (/\[[^\]\n]{2,}\]/.test(text)) fehler = 'Im Text steht noch ein Platzhalter in eckigen Klammern: ' + text.match(/\[[^\]\n]{2,}\]/)[0] + ' – bitte in ' + textDatei + ' ersetzen und dann erneut freigeben.';
else if (text.length > 3000) fehler = 'Der Text ist mit ' + text.length + ' Zeichen länger als die 3.000 Zeichen, die LinkedIn erlaubt.';
else if (p.format !== 'text' && !datei) fehler = 'Die Datei für das Format „' + p.format + '“ fehlt im Themenordner (' + ort + ').';

// Titel des PDF-Dokuments: Überschrift der ersten Folie (kanalneutral), sonst Thema-Titel ohne Kanal-Zusatz
const dokTitel = String(p.folie1 || '').replace(/\*\*/g, '').trim() || String(p.titel || '').replace(/\s*(?:für|fürs|auf)\s+(?:Instagram|LinkedIn|WhatsApp)\b[^.?!]*[.?!]?/gi, '').trim() || 'Beitrag';

// LinkedIn "little text": Sonderzeichen maskieren, Hashtags als Vorlage
const maske = s => s.replace(/[\\|{}@\[\]()<>*_~]/g, c => '\\' + c).replace(/#/g, '\\#');
const teile = [];
let rest = text, m;
const re = /#([\p{L}\p{N}]+)/u;
while ((m = rest.match(re))) {
  teile.push(maske(rest.slice(0, m.index)));
  teile.push('{hashtag|\\#|' + m[1] + '}');
  rest = rest.slice(m.index + m[0].length);
}
teile.push(maske(rest));

return [{ json: { post_id: p.post_id, kanal: p.kanal, titel: String(p.titel || '') + (seite ? ' (Unternehmensseite)' : ''), dok_titel: dokTitel, format: p.format, room_id: p.room_id, matrix_user_id: p.matrix_user_id, ordner: p.ordner, datei_pfad: datei ? p.ordner + '/' + datei : '', ort, autor: seite ? 'urn:li:organization:' + (p.linkedin_org || '') : 'urn:li:person:' + (prof.sub || ''), commentary: teile.join(''), text_quelle: quelle, zeichen: text.length, fehler, bereit: !fehler } }];

// Chat-Layout (Vorgabe Stefan, 11.10.2026): Titel fett mit Doppelpunkt, Inhalt direkt darunter, Leerzeile zwischen Bloecken, keine Listenpunkte, keine Emojis
const esc = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const roh = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '');
const zeileHtml = z => typeof z === 'string' ? esc(z) : (z.html !== undefined ? z.html : (z.kursiv ? '<em>' + esc(z.t) + '</em>' : esc(z.t)));
const zeileText = z => typeof z === 'string' ? roh(z) : (z.behalten ? String(z.t ?? '') : roh(z.t));
const render = bloecke => {
  const b = bloecke.filter(x => x).map(x => Object.assign({}, x, { zeilen: (x.zeilen || []).filter(z => z !== undefined && z !== null && z !== '') })).filter(x => x.titel || x.zeilen.length);
  return {
    html: b.map(x => (x.titel ? '<strong>' + esc(x.titel) + '</strong>' + ((x.zeilen || []).length ? '<br>' : '') : '') + (x.zeilen || []).map(zeileHtml).join('<br>')).join('<br><br>'),
    text: b.map(x => (x.titel ? roh(x.titel) + ((x.zeilen || []).length ? '\n' : '') : '') + (x.zeilen || []).map(zeileText).join('\n')).join('\n\n')
  };
};
const t = $('Text prüfen').first().json;
let fehler = t.fehler || '';
let url = '';
if (!fehler) {
  const up = $('Upload vorbereiten').isExecuted ? $('Upload vorbereiten').first().json : null;
  const dl = $('Datei laden (SPEICHER 1)').isExecuted ? $('Datei laden (SPEICHER 1)').first().json : null;
  const put = $('Datei hochladen').isExecuted ? $('Datei hochladen').first().json : null;
  const r = $('Beitrag veröffentlichen').isExecuted ? $('Beitrag veröffentlichen').first().json : {};
  const msg = x => { const b = x && x.body; return (b && (b.message || (typeof b === 'string' ? b : JSON.stringify(b)))) || (x && (x.error && (x.error.message || x.error))) || ('Status ' + (x && x.statusCode)); };
  if (up && up.statusCode !== 200) fehler = 'LinkedIn-Upload konnte nicht vorbereitet werden: ' + msg(up);
  else if (dl && dl.ok !== true) fehler = 'Die Datei konnte nicht aus dem Speicherort (' + (dl.ort || t.ort || '?') + ') geladen werden: ' + (dl.fehler || 'unbekannter Fehler');
  else if (put && !(put.statusCode >= 200 && put.statusCode < 300)) fehler = 'Datei-Upload zu LinkedIn fehlgeschlagen: ' + msg(put);
  else if (r.statusCode === 201) {
    const h = r.headers || {};
    const urn = h['x-restli-id'] || h['x-linkedin-id'] || '';
    url = urn ? 'https://www.linkedin.com/feed/update/' + urn + '/' : 'https://www.linkedin.com/in/me/recent-activity/all/';
  } else fehler = 'LinkedIn hat den Beitrag abgelehnt: ' + msg(r);
}
const ok = !fehler;
const n = ok
  ? render([{ titel: 'Auf LinkedIn veröffentlicht:', zeilen: [t.titel, { t: url, html: '<a href="' + esc(url) + '">' + esc(url) + '</a>' }] }])
  : render([{ titel: 'Nicht auf LinkedIn veröffentlicht:', zeilen: [t.titel] }, { titel: 'Grund:', zeilen: [fehler] }, { zeilen: ['Der Auftrag steht auf „Fehler“. Nach der Korrektur einfach erneut freigeben.'] }]);
return [{ json: { post_id: t.post_id, status: ok ? 'gepostet' : 'fehler', post_url: url, fehler, room_id: t.room_id, matrix_user_id: t.matrix_user_id, text: n.text, html: n.html } }];

// Text vorbereiten: LinkedIn-Text des Themas aus dem Speicherort holen (Auftrag an SPEICHER 1); Unternehmensseite: linkedin-seite.txt
const p = $('Fälligen Post holen').first().json;
return [{ json: { aktion: 'holen', bereich: 'ally', pfad: (p.ordner || '_') + (p.kanal === 'linkedin_seite' ? '/LinkedIn/linkedin-seite.txt' : '/LinkedIn/linkedin-profil.txt') } }];

// Dateien vorbereiten: geholten Text lesen und prüfen lassen, welche Dateien im Themenordner liegen (Aufträge an SPEICHER 1)
const p = $('Fälligen Post holen').first().json;
const h = $input.first();
let lesetext = '';
if (h && h.json && h.json.ok === true && h.binary && h.binary.datei) {
  try { lesetext = (await this.helpers.getBinaryDataBuffer(0, 'datei')).toString('utf8').replace(/^﻿/, '').trim(); } catch (e) { lesetext = ''; }
}
// Erste Datei ist der Text des Kanals (persönliches Profil oder Unternehmensseite)
const KANDIDATEN = [p.kanal === 'linkedin_seite' ? 'LinkedIn/linkedin-seite.txt' : 'LinkedIn/linkedin-profil.txt', 'LinkedIn/karussell-linkedin.pdf', 'karussell-linkedin.pdf', 'Instagram-Post/karussell-01.jpg', 'Instagram-Post/karussell-01.png', 'karussell-01.png'];
const ordner = p.ordner || '_';
return KANDIDATEN.map((rel, i) => ({ json: Object.assign({ aktion: 'pruefen', bereich: 'ally', pfad: ordner + '/' + rel, rel }, i === 0 ? { lesetext } : {}) }));

