-- Benachrichtigung in der Oberfläche zur Chat-Nachricht (BA10, Stefan 20.10.2026), Art marketing_veroeffentlicht, gleiche Person wie im Chat.
-- Wirft nie einen Fehler; die Chat-Nachricht läuft unverändert und unabhängig davon (eigener Zweig, läuft vor dem Senden).
SELECT ally_benachrichtigung_aus_chat($1::text, 'marketing_veroeffentlicht', NULLIF($2::text, ''), NULL, NULL, 'MARKETING 3') AS r;
